class Solution {
  public java.util.List<Integer> countOfPeaks(int[] nums, int[][] queries) {
    Fenwick bit = new Fenwick(nums.length);
    for (int i = 1; i + 1 < nums.length; i++) if (isPeak(nums, i)) bit.add(i, 1);
    java.util.List<Integer> answer = new java.util.ArrayList<>();
    for (int[] q : queries) {
      if (q[0] == 1) answer.add(bit.sum(q[2] - 1) - bit.sum(q[1]));
      else {
        int i = q[1];
        for (int j = Math.max(1, i - 1); j <= Math.min(nums.length - 2, i + 1); j++)
          if (isPeak(nums, j)) bit.add(j, -1);
        nums[i] = q[2];
        for (int j = Math.max(1, i - 1); j <= Math.min(nums.length - 2, i + 1); j++)
          if (isPeak(nums, j)) bit.add(j, 1);
      }
    }
    return answer;
  }

  private boolean isPeak(int[] a, int i) {
    return a[i] > a[i - 1] && a[i] > a[i + 1];
  }

  static class Fenwick {
    int[] tree;

    Fenwick(int n) {
      tree = new int[n + 1];
    }

    void add(int i, int v) {
      for (; i < tree.length; i += i & -i) tree[i] += v;
    }

    int sum(int i) {
      int s = 0;
      for (; i > 0; i -= i & -i) s += tree[i];
      return s;
    }
  }
}
